float hash21(vec2 p){
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float vnoise(vec2 p){
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i),                hash21(i + vec2(1.0, 0.0)), f.x),
               mix(hash21(i + vec2(0.0,1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm3(vec2 p){
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 3; i++){ v += a * vnoise(p); p = p * 2.07 + 11.3; a *= 0.5; }
    return v;
}
// 32-band spectrum read with CONSTANT indices only -> valid GLSL ES 1.00
float spec(float a){
    float b1 = u_audio_spectrum[1],  b2 = u_audio_spectrum[5];
    float b3 = u_audio_spectrum[9],  b4 = u_audio_spectrum[14];
    float b5 = u_audio_spectrum[20], b6 = u_audio_spectrum[27];
    float x = fract(a) * 6.0;
    float i = floor(x);
    float f = x - i;  f = f * f * (3.0 - 2.0 * f);
    if      (i < 0.5) return mix(b1, b2, f);
    else if (i < 1.5) return mix(b2, b3, f);
    else if (i < 2.5) return mix(b3, b4, f);
    else if (i < 3.5) return mix(b4, b5, f);
    else if (i < 4.5) return mix(b5, b6, f);
    return b6;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2  res = u_resolution;
    vec2  p   = (fragCoord * 2.0 - res) / min(res.x, res.y);
    float t   = u_time * u_speed;
    float r   = length(p);
    float a   = atan(p.y, p.x) / 6.28318531;

    vec2 q = p * 1.6;
    vec2 w = vec2(fbm3(q + vec2(0.0, t * 0.05)), fbm3(q + vec2(5.2, -t * 0.04)));
    float n = fbm3(q + 1.8 * w + vec2(t * 0.03, 0.0));

    vec3 col = vec3(0.006, 0.008, 0.022);
    col = mix(col, u_color1 * 0.35, smoothstep(0.35, 0.85, n) * 0.85);
    col = mix(col, u_color2 * 0.40, smoothstep(0.55, 0.95, n * w.x + 0.25) * 0.60);

    vec2  sid = floor(p * 46.0);
    float sh  = hash21(sid);
    if (sh > 0.972){
        vec2 sf = fract(p * 46.0) - 0.5;
        vec2 so = vec2(hash21(sid + 3.17), hash21(sid + 7.71)) - 0.5;
        col += vec3(0.85, 0.90, 1.0)
             * (1.0 - smoothstep(0.0, 0.10, length(sf - so * 0.55)))
             * (0.5 + 0.5 * sin(t * 2.0 + sh * 40.0)) * 0.85;
    }

    float s   = 0.5 * (spec(a - t * 0.06) + spec(a - t * 0.06 + 0.03));
    float tgt = 0.52 + 0.26 * s + 0.06 * s * u_audio_vol
                     + 0.030 * sin(a * 6.28318531 * 4.0 - t * 0.7);
    float d   = abs(r - tgt);
    float line  = exp(-d * d * 150.0);
    float line2 = exp(-(r - tgt * 0.66) * (r - tgt * 0.66) * 260.0) * 0.38;
    float line3 = exp(-(r - tgt * 1.34) * (r - tgt * 1.34) * 200.0) * 0.24;
    vec3 ringCol = mix(u_color1, u_accent, 0.35 + 0.65 * s);
    col += ringCol * (line + line2 + line3) * (0.8 + u_intensity * 0.4);
    col += ringCol * line * line * 0.30;

    float rays = 0.5 + 0.5 * sin(a * 6.28318531 * 16.0 + t * 0.5);
    rays = rays * rays; rays = rays * rays;
    col += u_accent * rays * exp(-abs(r - tgt) * 3.0)
         * (0.10 + 0.60 * u_audio_treble) * 0.22;

    col += mix(u_color1, u_accent, 0.5) * exp(-r * 7.0)
         * (0.35 + 0.65 * u_audio_bass) * 0.55;
    col += u_color2 * 0.05 * exp(-r * 2.4) * (0.5 + u_audio_mid);

    col *= 1.0 - 0.24 * dot(p * 0.60, p * 0.60);
    col  = pow(max(col, 0.0), vec3(0.88));
    fragColor = vec4(col, 1.0);
}

